import os
import json
from openai import OpenAI

def normalize_expense_fields(document_content: str) -> dict:
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    expense_schema = {
        "name": "expense_extraction",
        "strict": True,
        "schema": {
            "type": "object",
            "properties": {
                "vendor_name": {"type": "string"},
                "transaction_date": {"type": "string", "format": "date"},
                "total_amount": {"type": "number"},
                "currency": {"type": "string"},
                "tax_amount": {"type": "number"},
                "expense_category": {
                    "type": "string",
                    "enum": ["Travel", "Meals", "Supplies", "Software", "Utilities", "Other"]
                }
            },
            "required": ["vendor_name", "transaction_date", "total_amount", "currency"],
            "additionalProperties": False
        }
    }

    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[
            {
                "role": "system",
                "content": "You are an expert data extraction engine. Parse the provided document text, identify the expense fields, and normalize them into the exact JSON schema provided. Ensure dates are strictly YYYY-MM-DD and monetary values are numeric."
            },
            {
                "role": "user",
                "content": document_content
            }
        ],
        response_format={"type": "json_schema", "json_schema": expense_schema},
        temperature=0.0
    )

    return json.loads(response.choices[0].message.content)
